/**
 *  This test case verifies CBRD-25472: COMMENT on a parameter of a PL/CSQL stored function.
 *  Revised for CBRD-26470: test_func2 calls test_func1 as a function and assigns its value,
 *  since a function can no longer be called as a procedure.
 *
 *  Coverage:
 *    Case 1: a parameter comment with a default value and special characters
 *    Case 2: a parameter comment without a default value, in a function that calls test_func1
 *    Case 3: a parameter comment of a recursive function
 *    Case 4: a parameter comment over the maximum length fails, and one of the maximum length
 *            (1024 bytes) is accepted
 *    Case 5: the parameter comments stored in db_stored_procedure_args
 */

--+ server-message on

evaluate 'Case 1: a parameter comment with a default value and special characters';
create or replace function test_func1(a int := 1 comment 'test sp char 123`~!@#$%^&*()_-=+\;,./?:;"[]{}\<>') return varchar
as
begin
    return 'func1 param: ' || a;
end;

select test_func1() from dual;


evaluate 'Case 2: a parameter comment without a default value';
create or replace function test_func2(a int comment 'param comment without default value') return varchar
as
    v varchar;
begin
    v := test_func1(3);
    return 'func2 param: ' || a;
end;

select test_func2(10) from dual;


evaluate 'Case 3: a parameter comment of a recursive function';
create or replace function test_func3(num int comment 'recursive function') return int
as
begin
    if num = 0 then
        return 1;
    else
        return num * test_func3(num-1);
    end if;
end;

select test_func3(5) from dual;


evaluate 'Case 4: a parameter comment over the maximum length fails, and one of 1024 bytes is accepted';
create or replace function test_func4(num int comment '_') return varchar
as
begin
    return 'maximum comment length over';
end;
create or replace function test_func4(num int comment '') return varchar
as
begin
    return 'maximum comment length';
end;

select test_func4(99) from dual;


evaluate 'Case 5: the parameter comments stored in db_stored_procedure_args';
select sp_name, arg_name, comment from db_stored_procedure_args where comment is not null order by sp_name;

drop function test_func1;
drop function test_func2;
drop function test_func3;
drop function test_func4;

--+ server-message off
